                    result = TfurqNotEqualEvalNode.Create(result, CompileLevel3(true));
                    break;
                case etSimular:
                    result = TfurqSimularEvalNode.Create(result, CompileLevel3(true));
                    break;
                case etGreater:
                    result = TfurqGreaterEvalNode.Create(result, CompileLevel3(true));
                    break;
                case etLesser:
                    result = TfurqLesserEvalNode.Create(result, CompileLevel3(true));
                    break;
                case etGreaterOrEqual:
                    result = TfurqGreaterOrEqualEvalNode.Create(result, CompileLevel3(true));
                    break;
                case etLesserOrEqual:
                    result = TfurqLesserOrEqualEvalNode.Create(result, CompileLevel3(true));
                    break;
                default:
                    break;
                    break;
            }
        }
        return result;
    }
    
    private TfurqEvalNode CompileLevel3(in bool aSkip)
    {
        TfurqEvalNode result;
        result = CompileLevel4(aSkip);
        while (true)
        {
            switch (f_Lexer.Token)
            {
                case etPlus:
                    result = TfurqSummaEvalNode.Create(result, CompileLevel4(true));
                    break;
                case etMinus:
                    result = TfurqSubtractEvalNode.Create(result, CompileLevel4(true));
                    break;
                default:
                    break;
                    break;
            }
        }
        return result;
    }
    
    private TfurqEvalNode CompileLevel4(in bool aSkip)
    {
        TfurqEvalNode result;
        result = CompileLevel5(aSkip);
        while (true)
        {
            switch (f_Lexer.Token)
            {
                case etMultiply:
                    result = TfurqMultiplyEvalNode.Create(result, CompileLevel5(true));
                    break;
                case etDivide:
                    result = TfurqDivideEvalNode.Create(result, CompileLevel5(true));
                    break;
                default:
                    break;
                    break;
            }
        }
        return result;
    }
    
    private TfurqEvalNode CompileLevel5(in bool aSkip)
    {
        TfurqEvalNode result;
        if (aSkip)
        {
            f_Lexer.NextToken();
        }
        switch (f_Lexer.Token)
        {
            case etPlus:
                result = CompileLevel5(true);
                break;
            case etMinus:
                result = TfurqNegateEvalNode.Create(CompileLevel5(true));
                break;
            case etNot:
                result = TfurqNotEvalNode.Create(CompileLevel5(true));
                break;
            default:
                result = CompileFactor;
                break;
        }
        return result;
    }
    
    private void CompileSource()
    {
        f_Expression = null;
        try
        {
            f_Expression = CompileLevel0(false);
        }
        catch (Exception)
        {
            f_Expression = null;
            throw;
        }
    }
    
    private Variant GetIdentifierValue(string aIdentName)
    {
        string l_Temp;
        int l_Range;
        Variant result;
    
        if (AnsiStartsText("rnd", aIdentName))
        {
            l_Temp = Copy(aIdentName, 4, MaxInt);
            if (l_Temp != "")
            {
                l_Range = StrToIntDef(l_Temp, 0);
                if (l_Range > 0)
                {
                    result = (Random(l_Range) + 1);
                    return result;
                }
            }
            else
            {
                result = Random;
                return result;
            }
        }
        if (f_Context.IsVariableExists(aIdentName))
        {
            result = f_Context.Variables[aIdentName];
        }
        else
        {
            if (f_Context.Inventory.IndexOf(aIdentName) != ( - 1))
            {
                result = 1;
            }
            else
            {
                result = 0;
            }
        }
        return result;
    }
    
    private Extended GetInventoryAmount(string aName, Extended anAmount)
    {
        int l_Idx;
        Extended result;
    
        result = 0.0;
        l_Idx = f_Context.Inventory.IndexOf(aName);
        if ((l_Idx >= 0) & (f_Context.Inventory.Variants[l_Idx] >= anAmount))
        {
            result = 1.0;
        }
        return result;
    }
    
    private Variant pm_GetResultValue()
    {
        Variant result;
        if (f_Expression != null)
        {
            result = f_Expression.Evaluate;
        }
        else
        {
            result = Unassigned;
        }
        return result;
    }
    
    private string pm_GetSource()
    {
        string result;
        result = f_Lexer.Source;
        return result;
    }
    
    private void pm_SetSource(in string Value)
    {
        if (f_Lexer.Source != Value)
        {
            f_Lexer.Source = Value;
            CompileSource();
        }
    }
    
}

